package com.chess.engine.move;

import com.chess.engine.board.Bitboard;

/**
 * Move encoding as a 32-bit integer.
 *
 * Bit layout:
 *   bits  0-5:  from square (0-63)
 *   bits  6-11: to square (0-63)
 *   bits 12-13: promotion piece (0=knight, 1=bishop, 2=rook, 3=queen)
 *   bits 14-15: move type (0=normal, 1=castling, 2=en passant, 3=promotion)
 *   bits 16-19: captured piece (piece index 0-11, 15=none)
 *   bits 20-23: moved piece (piece index 0-11)
 */
public final class Move {

    public static final int NONE = 0;

    // Move types
    public static final int NORMAL = 0;
    public static final int CASTLING = 1;
    public static final int EN_PASSANT = 2;
    public static final int PROMOTION = 3;

    // Piece indices (used in captured/moved fields)
    public static final int WP = 0, WN = 1, WB = 2, WR = 3, WQ = 4, WK = 5;
    public static final int BP = 6, BN = 7, BB = 8, BR = 9, BQ = 10, BK = 11;
    public static final int NO_PIECE = 15;

    private Move() {}

    public static int encode(int from, int to, int promo, int type, int captured, int moved) {
        return from | (to << 6) | (promo << 12) | (type << 14) | (captured << 16) | (moved << 20);
    }

    public static int from(int move) {
        return move & 0x3F;
    }

    public static int to(int move) {
        return (move >>> 6) & 0x3F;
    }

    public static int promo(int move) {
        return (move >>> 12) & 0x3;
    }

    public static int type(int move) {
        return (move >>> 14) & 0x3;
    }

    public static int captured(int move) {
        return (move >>> 16) & 0xF;
    }

    public static int moved(int move) {
        return (move >>> 20) & 0xF;
    }

    public static boolean isCapture(int move) {
        return captured(move) != NO_PIECE;
    }

    public static boolean isPromotion(int move) {
        return type(move) == PROMOTION;
    }

    public static boolean isCastling(int move) {
        return type(move) == CASTLING;
    }

    public static boolean isEnPassant(int move) {
        return type(move) == EN_PASSANT;
    }

    /** Returns piece type (0=pawn..5=king) from piece index. */
    public static int pieceType(int piece) {
        return piece % 6;
    }

    /** Returns color (0=white, 1=black) from piece index. */
    public static int pieceColor(int piece) {
        return piece / 6;
    }

    /** Promotion piece index for the given color. promo: 0=N,1=B,2=R,3=Q */
    public static int promoPiece(int promo, int color) {
        return color * 6 + promo + 1; // +1 because pawn=0, knight=1, etc.
    }

    public static String toUCI(int move) {
        if (move == NONE) return "0000";
        StringBuilder sb = new StringBuilder();
        sb.append(Bitboard.squareToString(from(move)));
        sb.append(Bitboard.squareToString(to(move)));
        if (type(move) == PROMOTION) {
            sb.append("nbrq".charAt(promo(move)));
        }
        return sb.toString();
    }

    public static String toString(int move) {
        return toUCI(move);
    }
}

