import com.chess.engine.board.Bitboard;

/**
 * Precomputed attack tables for knights, kings, and pawns.
 */
public final class AttackTables {

    public static final long[] KNIGHT_ATTACKS = new long[64];
    public static final long[] KING_ATTACKS = new long[64];
    /** PAWN_ATTACKS[color][square] */
    public static final long[][] PAWN_ATTACKS = new long[2][64];

    static {
        initKnightAttacks();
        initKingAttacks();
        initPawnAttacks();
    }

    private AttackTables() {}

    private static void initKnightAttacks() {
        for (int sq = 0; sq < 64; sq++) {
            long bb = Bitboard.bit(sq);
            long attacks = 0L;
            attacks |= (bb << 17) & Bitboard.NOT_FILE_A;   // up 2 right 1
            attacks |= (bb << 15) & Bitboard.NOT_FILE_H;   // up 2 left 1
            attacks |= (bb << 10) & Bitboard.NOT_FILE_AB;  // up 1 right 2
            attacks |= (bb << 6)  & Bitboard.NOT_FILE_GH;  // up 1 left 2
            attacks |= (bb >>> 6)  & Bitboard.NOT_FILE_AB; // down 1 right 2
            attacks |= (bb >>> 10) & Bitboard.NOT_FILE_GH; // down 1 left 2
            attacks |= (bb >>> 15) & Bitboard.NOT_FILE_A;  // down 2 right 1
            attacks |= (bb >>> 17) & Bitboard.NOT_FILE_H;  // down 2 left 1
            KNIGHT_ATTACKS[sq] = attacks;
        }
    }

    private static void initKingAttacks() {
        for (int sq = 0; sq < 64; sq++) {
            long bb = Bitboard.bit(sq);
            long attacks = 0L;
            attacks |= (bb << 8);                           // up
            attacks |= (bb >>> 8);                          // down
            attacks |= (bb << 1)  & Bitboard.NOT_FILE_A;   // right
            attacks |= (bb >>> 1) & Bitboard.NOT_FILE_H;   // left
            attacks |= (bb << 9)  & Bitboard.NOT_FILE_A;   // up-right
            attacks |= (bb << 7)  & Bitboard.NOT_FILE_H;   // up-left
            attacks |= (bb >>> 7) & Bitboard.NOT_FILE_A;   // down-right
            attacks |= (bb >>> 9) & Bitboard.NOT_FILE_H;   // down-left
            KING_ATTACKS[sq] = attacks;
        }
    }

    private static void initPawnAttacks() {
        for (int sq = 0; sq < 64; sq++) {
            long bb = Bitboard.bit(sq);
            // White pawn attacks (moving up)
            PAWN_ATTACKS[0][sq] = ((bb << 7) & Bitboard.NOT_FILE_H) | ((bb << 9) & Bitboard.NOT_FILE_A);
            // Black pawn attacks (moving down)
            PAWN_ATTACKS[1][sq] = ((bb >>> 9) & Bitboard.NOT_FILE_H) | ((bb >>> 7) & Bitboard.NOT_FILE_A);
        }
    }
}

