package com.chess.engine.board;

/**
 * Zobrist hashing tables for board state hashing.
 * Uses a seeded PRNG for reproducible keys.
 */
public final class Zobrist {

    /** Piece keys: [pieceIndex 0-11][square 0-63] */
    public static final long[][] PIECE_KEYS = new long[12][64];

    /** Side to move key (XOR when black to move) */
    public static final long SIDE_KEY;

    /** Castling right keys [0-15] */
    public static final long[] CASTLING_KEYS = new long[16];

    /** En passant file keys [0-7] */
    public static final long[] EP_KEYS = new long[8];

    private static long seed = 1070372L;

    static {
        for (int piece = 0; piece < 12; piece++) {
            for (int sq = 0; sq < 64; sq++) {
                PIECE_KEYS[piece][sq] = nextRandom();
            }
        }
        SIDE_KEY = nextRandom();
        for (int i = 0; i < 16; i++) {
            CASTLING_KEYS[i] = nextRandom();
        }
        for (int i = 0; i < 8; i++) {
            EP_KEYS[i] = nextRandom();
        }
    }

    private Zobrist() {}

    /** Simple 64-bit xorshift PRNG. */
    private static long nextRandom() {
        seed ^= seed << 13;
        seed ^= seed >>> 7;
        seed ^= seed << 17;
        return seed;
    }
}

