package com.chess.engine.move;

/**
 * Array-backed move list with scoring for move ordering.
 * Uses partial selection sort via pickBest().
 */
public final class MoveList {

    private static final int MAX_MOVES = 256;

    public final int[] moves = new int[MAX_MOVES];
    public final int[] scores = new int[MAX_MOVES];
    public int size = 0;

    public void add(int move) {
        moves[size] = move;
        scores[size] = 0;
        size++;
    }

    public void add(int move, int score) {
        moves[size] = move;
        scores[size] = score;
        size++;
    }

    public void clear() {
        size = 0;
    }

    /**
     * Partial selection sort: find the best-scored move at or after index,
     * swap it to position index, and return it.
     */
    public int pickBest(int index) {
        int bestIdx = index;
        int bestScore = scores[index];
        for (int i = index + 1; i < size; i++) {
            if (scores[i] > bestScore) {
                bestScore = scores[i];
                bestIdx = i;
            }
        }
        if (bestIdx != index) {
            // Swap moves
            int tmpMove = moves[index];
            moves[index] = moves[bestIdx];
            moves[bestIdx] = tmpMove;
            // Swap scores
            int tmpScore = scores[index];
            scores[index] = scores[bestIdx];
            scores[bestIdx] = tmpScore;
        }
        return moves[index];
    }
}

