/**
 * Static Exchange Evaluation for capture sequence analysis.
 */
public final class SEE {

    private static final int[] SEE_VALUES = {100, 320, 330, 500, 900, 20000};

    private SEE() {}

    /**
     * Returns the SEE value for a capture move.
     * Positive means the capture wins material.
     */
    public static int see(Board board, int move) {
        int from = Move.from(move);
        int to = Move.to(move);
        int target = Move.captured(move);
        int attacker = Move.moved(move);

        if (target == Move.NO_PIECE) return 0;

        int[] gain = new int[32];
        int depth = 0;

        long mayXray = board.pieces[Board.WP] | board.pieces[Board.BP]
                     | board.pieces[Board.WB] | board.pieces[Board.BB]
                     | board.pieces[Board.WR] | board.pieces[Board.BR]
                     | board.pieces[Board.WQ] | board.pieces[Board.BQ];

        long occ = board.occupancy[2];
        long fromBit = Bitboard.bit(from);

        gain[depth] = SEE_VALUES[target % 6];

        int side = Move.pieceColor(attacker);

        do {
            depth++;
            gain[depth] = SEE_VALUES[attacker % 6] - gain[depth - 1]; // speculative store

            if (Math.max(-gain[depth - 1], gain[depth]) < 0) break; // pruning

            occ ^= fromBit; // remove attacker from occupancy

            // Discover X-ray attacks
            if ((fromBit & mayXray) != 0) {
                // Recalculate sliding attacks through the removed piece
                // (handled by using updated occ in getSmallestAttacker)
            }

            side ^= 1;

            fromBit = getSmallestAttacker(board, to, side, occ);
            if (fromBit == 0) break;

            from = Bitboard.lsb(fromBit);
            attacker = board.pieceAt[from];
        } while (true);

        while (--depth > 0) {
            gain[depth - 1] = -Math.max(-gain[depth - 1], gain[depth]);
        }

        return gain[0];
    }

    /** Returns true if the SEE value is >= threshold. Faster than full SEE. */
    public static boolean seeGe(Board board, int move, int threshold) {
        return see(board, move) >= threshold;
    }

    private static long getSmallestAttacker(Board board, int sq, int side, long occ) {
        int base = side * 6;

        // Pawns
        long pawns = AttackTables.PAWN_ATTACKS[side ^ 1][sq] & board.pieces[base] & occ;
        if (pawns != 0) return pawns & -pawns;

        // Knights
        long knights = AttackTables.KNIGHT_ATTACKS[sq] & board.pieces[base + 1] & occ;
        if (knights != 0) return knights & -knights;

        // Bishops
        long bishopAttacks = MagicBitboards.bishopAttacks(sq, occ);
        long bishops = bishopAttacks & board.pieces[base + 2] & occ;
        if (bishops != 0) return bishops & -bishops;

        // Rooks
        long rookAttacks = MagicBitboards.rookAttacks(sq, occ);
        long rooks = rookAttacks & board.pieces[base + 3] & occ;
        if (rooks != 0) return rooks & -rooks;

        // Queens
        long queens = (bishopAttacks | rookAttacks) & board.pieces[base + 4] & occ;
        if (queens != 0) return queens & -queens;

        // King
        long king = AttackTables.KING_ATTACKS[sq] & board.pieces[base + 5] & occ;
        if (king != 0) return king & -king;

        return 0;
    }
}

