/**
 * History heuristic: [color][from][to] counters.
 * Bonus = depth*depth on beta cutoff. Aged by halving.
 */
public final class HistoryTable {

    private final int[][][] table = new int[2][64][64];

    public void update(int color, int from, int to, int depth) {
        table[color][from][to] += depth * depth;
        // Cap to prevent overflow
        if (table[color][from][to] > 1_000_000) {
            age();
        }
    }

    public int get(int color, int from, int to) {
        return table[color][from][to];
    }

    /** Age all entries by halving. */
    public void age() {
        for (int c = 0; c < 2; c++) {
            for (int f = 0; f < 64; f++) {
                for (int t = 0; t < 64; t++) {
                    table[c][f][t] /= 2;
                }
            }
        }
    }

    public void clear() {
        for (int c = 0; c < 2; c++) {
            for (int f = 0; f < 64; f++) {
                for (int t = 0; t < 64; t++) {
                    table[c][f][t] = 0;
                }
            }
        }
    }
}

