package com.chess.engine.search;

/**
 * Time allocation for search.
 */
public final class TimeManager {

    private TimeManager() {}

    /**
     * Calculate time to allocate for this move.
     * @param timeLeft time remaining in ms
     * @param increment increment per move in ms
     * @param movesToGo moves until next time control (0 = sudden death)
     * @return allocated time in ms
     */
    public static long allocateTime(long timeLeft, long increment, int movesToGo) {
        if (movesToGo == 0) movesToGo = 30; // estimate ~30 moves remaining

        long baseTime = timeLeft / movesToGo;
        long incBonus = increment * 3 / 4;
        long allocated = baseTime + incBonus;

        // Don't use more than 50% of remaining time
        allocated = Math.min(allocated, timeLeft / 2);

        // Minimum 10ms
        return Math.max(allocated, 10);
    }
}

