    public boolean probe(long zobrist, TTEntry entry) {
        int index = (int) (zobrist) & mask;
        if (keys[index] != zobrist) return false;

        long packed = data[index];
        entry.move = (int) (packed & 0xFFFFFFFFL);
        entry.score = (short) ((packed >>> 32) & 0xFFFF);
        entry.depth = (int) ((packed >>> 48) & 0xFF);
        entry.flag = (int) ((packed >>> 56) & 0x3);
        return true;
    }

