/**
 * Killer move heuristic: 2 killers per ply.
 * Killer moves are quiet moves that caused a beta cutoff.
 */
public final class KillerMoves {

    private static final int MAX_PLY = 128;
    private static final int NUM_KILLERS = 2;

    private final int[][] killers = new int[MAX_PLY][NUM_KILLERS];

    public void store(int move, int ply) {
        if (move == killers[ply][0]) return;
        killers[ply][1] = killers[ply][0];
        killers[ply][0] = move;
    }

    public boolean isKiller(int move, int ply) {
        return killers[ply][0] == move || killers[ply][1] == move;
    }

    public int getKiller(int ply, int index) {
        return killers[ply][index];
    }

    public void clear() {
        for (int i = 0; i < MAX_PLY; i++) {
            killers[i][0] = 0;
            killers[i][1] = 0;
        }
    }
}

