import com.chess.engine.board.Bitboard;
import com.chess.engine.board.Board;

/**
 * Pawn structure evaluation with dedicated pawn hash table.
 * Evaluates doubled, isolated, and passed pawns.
 */
public final class PawnStructure {

    // Pawn hash table
    private static final int PAWN_HASH_SIZE = 16384; // 16K entries
    private static final long[] pawnHashKeys = new long[PAWN_HASH_SIZE];
    private static final int[] pawnHashScores = new int[PAWN_HASH_SIZE];
    private static final int PAWN_HASH_MASK = PAWN_HASH_SIZE - 1;

    // Bonuses and penalties
    private static final int DOUBLED_PENALTY = 10;
    private static final int ISOLATED_PENALTY = 15;
    private static final int BACKWARD_PENALTY = 8;
    private static final int[] PASSED_BONUS = {0, 10, 20, 35, 60, 100, 150, 0}; // by rank

    // Adjacent file masks
    private static final long[] ADJACENT_FILES = new long[8];
    // Passed pawn masks
    private static final long[][] PASSED_MASKS = new long[2][64];

    static {
        for (int f = 0; f < 8; f++) {
            ADJACENT_FILES[f] = 0;
            if (f > 0) ADJACENT_FILES[f] |= Bitboard.FILE_MASKS[f - 1];
            if (f < 7) ADJACENT_FILES[f] |= Bitboard.FILE_MASKS[f + 1];
        }

        for (int sq = 0; sq < 64; sq++) {
            int file = Bitboard.fileOf(sq);
            int rank = Bitboard.rankOf(sq);
            long fileMask = Bitboard.FILE_MASKS[file] | ADJACENT_FILES[file];

            // White passed pawn mask: all squares in front on file and adjacent files
            long whiteMask = 0;
            for (int r = rank + 1; r <= 7; r++) {
                whiteMask |= fileMask & Bitboard.RANK_MASKS[r];
            }
            PASSED_MASKS[Board.WHITE][sq] = whiteMask;

            // Black passed pawn mask
            long blackMask = 0;
            for (int r = rank - 1; r >= 0; r--) {
                blackMask |= fileMask & Bitboard.RANK_MASKS[r];
            }
            PASSED_MASKS[Board.BLACK][sq] = blackMask;
        }
    }

    private PawnStructure() {}

    public static int evaluate(Board board) {
        // Probe pawn hash
        int hashIndex = (int) (board.pawnKey & PAWN_HASH_MASK);
        if (pawnHashKeys[hashIndex] == board.pawnKey) {
            return pawnHashScores[hashIndex];
        }

        int score = 0;
        score += evaluatePawns(board, Board.WHITE);
        score -= evaluatePawns(board, Board.BLACK);

        // Store in pawn hash
        pawnHashKeys[hashIndex] = board.pawnKey;
        pawnHashScores[hashIndex] = score;

        return score;
    }

    private static int evaluatePawns(Board board, int color) {
        int score = 0;
        int pawnPiece = color * 6;
        long ourPawns = board.pieces[pawnPiece];
        long theirPawns = board.pieces[(color ^ 1) * 6];
        long pawns = ourPawns;

        while (pawns != 0) {
            int sq = Bitboard.lsb(pawns);
            pawns &= pawns - 1;
            int file = Bitboard.fileOf(sq);
            int rank = Bitboard.rankOf(sq);

            // Doubled pawn
            long pawnsOnFile = ourPawns & Bitboard.FILE_MASKS[file];
            if (Long.bitCount(pawnsOnFile) > 1) {
                score -= DOUBLED_PENALTY;
            }

            // Isolated pawn
            if ((ourPawns & ADJACENT_FILES[file]) == 0) {
                score -= ISOLATED_PENALTY;
            }

            // Passed pawn
            if ((theirPawns & PASSED_MASKS[color][sq]) == 0) {
                int passedRank = color == Board.WHITE ? rank : 7 - rank;
                score += PASSED_BONUS[passedRank];
            }
        }

        return score;
    }

    public static void clearHash() {
        java.util.Arrays.fill(pawnHashKeys, 0);
        java.util.Arrays.fill(pawnHashScores, 0);
    }
}

