    public static boolean isSquareAttacked(Board board, int sq, int attackerColor) {
        long occ = board.occupancy[2];
        int base = attackerColor * 6;

        // Pawn attacks (reverse lookup)
        if ((AttackTables.PAWN_ATTACKS[attackerColor ^ 1][sq] & board.pieces[base]) != 0) return true;
        // Knight attacks
        if ((AttackTables.KNIGHT_ATTACKS[sq] & board.pieces[base + 1]) != 0) return true;
        // Bishop/Queen diagonal
        long bishopQueen = board.pieces[base + 2] | board.pieces[base + 4];
        if ((MagicBitboards.bishopAttacks(sq, occ) & bishopQueen) != 0) return true;
        // Rook/Queen orthogonal
        long rookQueen = board.pieces[base + 3] | board.pieces[base + 4];
        if ((MagicBitboards.rookAttacks(sq, occ) & rookQueen) != 0) return true;
        // King
        if ((AttackTables.KING_ATTACKS[sq] & board.pieces[base + 5]) != 0) return true;

        return false;
    }

    /** Check if the side to move is in check. */
    public static boolean isInCheck(Board board) {
        return isSquareAttacked(board, board.kingSquare(board.sideToMove), board.sideToMove ^ 1);
    }

    // ---- Legality filter ----

    private static MoveList filterLegal(Board board, MoveList pseudoLegal) {
        MoveList legal = new MoveList();
        for (int i = 0; i < pseudoLegal.size; i++) {
            int move = pseudoLegal.moves[i];
            board.makeMove(move);
            // After making move, it's opponent's turn. Check if we left our king in check.
            if (!isSquareAttacked(board, board.kingSquare(board.sideToMove ^ 1), board.sideToMove)) {
                legal.add(move);
            }
            board.unmakeMove();
        }
        return legal;
    }

    // ---- Perft ----

    public static long perft(Board board, int depth) {
        if (depth == 0) return 1;

        MoveList moves = generateLegalMoves(board);
        if (depth == 1) return moves.size;

        long nodes = 0;
        for (int i = 0; i < moves.size; i++) {
            board.makeMove(moves.moves[i]);
            nodes += perft(board, depth - 1);
            board.unmakeMove();
        }
        return nodes;
    }

    /** Perft with divide (for debugging). */
    public static long perftDivide(Board board, int depth) {
        MoveList moves = generateLegalMoves(board);
        long total = 0;
        for (int i = 0; i < moves.size; i++) {
            int move = moves.moves[i];
            board.makeMove(move);
            long nodes = depth <= 1 ? 1 : perft(board, depth - 1);
