import com.chess.engine.board.Bitboard;
import com.chess.engine.board.Board;

/**
 * King safety evaluation: pawn shield and open file penalties.
 */
public final class KingSafety {

    // Pawn shield bonus for pawns in front of king
    private static final int PAWN_SHIELD_BONUS = 10;
    private static final int PAWN_SHIELD_CLOSE = 15;
    // Penalty for open/semi-open files near king
    private static final int OPEN_FILE_PENALTY = 15;
    private static final int SEMI_OPEN_FILE_PENALTY = 8;

    private KingSafety() {}

    public static int evaluate(Board board) {
        int score = 0;
        score += evaluateKingSafety(board, Board.WHITE);
        score -= evaluateKingSafety(board, Board.BLACK);
        return score;
    }

    private static int evaluateKingSafety(Board board, int color) {
        int score = 0;
        int kingSq = board.kingSquare(color);
        int kingFile = Bitboard.fileOf(kingSq);
        int kingRank = Bitboard.rankOf(kingSq);

        int pawnPiece = color * 6; // WP=0, BP=6
        long ourPawns = board.pieces[pawnPiece];
        long theirPawns = board.pieces[(color ^ 1) * 6];

        // Only evaluate pawn shield if king is on the flanks (castled)
        if (kingFile <= 2 || kingFile >= 5) {
            // Check files around the king for pawn shield
            int startFile = Math.max(0, kingFile - 1);
            int endFile = Math.min(7, kingFile + 1);

            for (int f = startFile; f <= endFile; f++) {
                long fileMask = Bitboard.FILE_MASKS[f];
                long ourPawnsOnFile = ourPawns & fileMask;

                if (ourPawnsOnFile != 0) {
                    // Find the closest pawn to the king on this file
                    int pawnRank;
                    if (color == Board.WHITE) {
                        pawnRank = Bitboard.rankOf(Bitboard.lsb(ourPawnsOnFile));
                    } else {
                        pawnRank = Bitboard.rankOf(Bitboard.msb(ourPawnsOnFile));
                    }
                    int dist = Math.abs(pawnRank - kingRank);
                    if (dist <= 1) {
                        score += PAWN_SHIELD_CLOSE;
                    } else if (dist <= 2) {
                        score += PAWN_SHIELD_BONUS;
                    }
                } else {
                    // No friendly pawn on this file
                    if ((theirPawns & fileMask) == 0) {
                        score -= OPEN_FILE_PENALTY; // fully open
                    } else {
                        score -= SEMI_OPEN_FILE_PENALTY;
                    }
                }
            }
        }

        return score;
    }
}

