package com.chess.engine.search;

import com.chess.engine.eval.Evaluation;

/**
 * Zobrist-keyed transposition table using two parallel arrays.
 * Power-of-2 size for fast index computation.
 */
public final class TranspositionTable {

    public static final int EXACT = 0;
    public static final int ALPHA = 1; // upper bound (fail-low)
    public static final int BETA = 2;  // lower bound (fail-high)

    private long[] keys;
    private long[] data;
    private int mask;

    /**
     * Data packing in 64-bit long:
     * bits  0-31: move (32 bits)
     * bits 32-47: score (16 bits, signed)
     * bits 48-55: depth (8 bits)
     * bits 56-57: flag (2 bits)
     * bits 58-63: age (6 bits)
     */

    public TranspositionTable(int sizeInMB) {
        int entries = (sizeInMB * 1024 * 1024) / 16; // 16 bytes per entry (key + data)
        // Round down to power of 2
        entries = Integer.highestOneBit(entries);
        keys = new long[entries];
        data = new long[entries];
        mask = entries - 1;
    }

    public void clear() {
        java.util.Arrays.fill(keys, 0);
        java.util.Arrays.fill(data, 0);
    }

    public void store(long zobrist, int move, int score, int depth, int flag, int ply) {
        int index = (int) (zobrist) & mask;

        // Adjust mate scores for storage
        score = scoreToTT(score, ply);

        long packed = (move & 0xFFFFFFFFL)
                    | ((long)(score & 0xFFFF) << 32)
                    | ((long)(depth & 0xFF) << 48)
                    | ((long)(flag & 0x3) << 56);

        // Always replace (simple scheme)
        keys[index] = zobrist;
        data[index] = packed;
    }

    /** Probe the TT. Returns true if hit. Sets fields in the provided TTEntry. */
    public boolean probe(long zobrist, TTEntry entry) {
        int index = (int) (zobrist) & mask;
        if (keys[index] != zobrist) return false;

        long packed = data[index];
        entry.move = (int) (packed & 0xFFFFFFFFL);
        entry.score = (short) ((packed >>> 32) & 0xFFFF);
        entry.depth = (int) ((packed >>> 48) & 0xFF);
        entry.flag = (int) ((packed >>> 56) & 0x3);
        return true;
    }

    /** Adjust mate scores for TT storage (ply-independent). */
    private static int scoreToTT(int score, int ply) {
        if (score >= Evaluation.MATE_BOUND) return score + ply;
        if (score <= -Evaluation.MATE_BOUND) return score - ply;
        return score;
    }

    /** Adjust mate scores from TT retrieval (ply-dependent). */
    public static int scoreFromTT(int score, int ply) {
        if (score >= Evaluation.MATE_BOUND) return score - ply;
        if (score <= -Evaluation.MATE_BOUND) return score + ply;
        return score;
    }

    public int size() {
        return mask + 1;
    }

    /** Reusable entry for probing. */
    public static final class TTEntry {
        public int move;
        public int score;
        public int depth;
        public int flag;
    }
}

